1	import {jest} from '@jest/globals';
2	import {WebSocket} from 'ws';
3	import {createMessageHandler} from './messageHandler.js';
4	import {createChatOrchestrator, TOOL_BUDGET_EXHAUSTED} from '../../orchestration/chatOrchestrator.js';
5	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
6	import {ToolRegistry} from '../../orchestration/tools/registry.js';
7	import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
8	import type {AIProvider, MessageChunk, ToolCall} from '../../types/ai.js';
9	import {AIError} from '../../types/ai.js';
10	import type {ChatSession, SessionEntry} from '../../types/session.js';
11	import type {OutgoingMessage} from '../../types/messages.js';
12	import {PerSessionLock} from '../../shared/perSessionLock.js';
13	import {deferred} from '../wsTestSupport.js';
14	
15	// The frames, in order, are the contract - above all for suppression, which retracts.
16	
17	// One line per frame; entries carry generated timestamps no assertion should read.
18	const wire = (sent: OutgoingMessage[]): string[] =>
19	  sent.map(frame => {
20	    if (frame.type === 'entry_upsert') {
21	      const content = 'content' in frame.entry ? frame.entry.content : '';
22	      return `upsert ${frame.index} ${frame.entry.role} ${JSON.stringify(content)}`;
23	    }
24	    if (frame.type === 'entry_delta') return `delta ${frame.index} ${JSON.stringify(frame.delta)}`;
25	    if (frame.type === 'entry_commit') return `commit ${frame.index}`;
26	    if (frame.type === 'entry_skip') return `skip ${frame.index}`;
27	    if (frame.type === 'error') return `error ${frame.code}`;
28	    if (frame.type === 'pong') return `pong ${frame.timestamp}`;
29	    return frame.type;
30	  });
31	
32	const text = (value: string): MessageChunk => ({type: 'text', text: value});
33	const STOP: MessageChunk = {type: 'stop', stopReason: 'end_turn'};
34	const SUPPRESS = {type: 'suppress_output'} as unknown as MessageChunk;
35	
36	interface StreamScript {
37	  failWith?: Error;
38	  pauseAfter?: {chunks: number; until: Promise<void>};
39	}
40	
41	const harness = (chunks: MessageChunk[], {failWith, pauseAfter}: StreamScript = {}) => {
42	  const sent: OutgoingMessage[] = [];
43	  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
44	
45	  const stream = async function* (): AsyncGenerator<MessageChunk> {
46	    for (const [position, chunk] of chunks.entries()) {
47	      if (pauseAfter && position === pauseAfter.chunks) await pauseAfter.until;
48	      yield chunk;
49	    }
50	    if (failWith) throw failWith;
51	  };
52	
53	  const processMessageStream = jest.fn(stream);
54	  const orchestrator = {processMessageStream} as unknown as ChatOrchestrator;
55	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
56	
57	  const handle = createMessageHandler(orchestrator);
58	
59	  return {
60	    session,
61	    processMessageStream,
62	    sent,
63	    frames: () => wire(sent),
64	    send: (raw: unknown = {type: 'user_message', content: 'hello'}, signal?: AbortSignal) =>
65	      handle(ws, session, raw, signal),
66	  };
67	};
68	
69	describe('the websocket message handler', () => {
70	  describe('dispatch', () => {
71	    it('rejects an unparseable message and never starts a stream', async () => {
72	      const h = harness([]);
73	
74	      await h.send({type: 'nonsense'});
75	
76	      const {calls} = h.processMessageStream.mock;
77	
78	      expect({frames: h.frames(), streams: calls.length}).toEqual({frames: ['error INVALID_MESSAGE'], streams: 0});
79	    });
80	
81	    it('answers a ping with the timestamp it was given', async () => {
82	      const h = harness([]);
83	
84	      await h.send({type: 'ping', timestamp: 1234});
85	
86	      expect(h.frames()).toEqual(['pong 1234']);
87	    });
88	  });
89	
90	  describe('a plain assistant reply', () => {
91	    it('sends the user entry, then the assistant entry, its delta, its commit and stream_end', async () => {
92	      const h = harness([text('hi there'), STOP]);
93	
94	      await h.send();
95	
96	      expect(h.frames()).toEqual([
97	        'upsert 0 user "hello"',
98	        'upsert 1 assistant ""',
99	        'delta 1 "hi there"',
100	        'commit 1',
101	        'stream_end',
102	      ]);
103	    });
104	
105	    it('leaves the committed assistant entry in the session, no longer streaming', async () => {
106	      const h = harness([text('hi there'), STOP]);
107	
108	      await h.send();
109	
110	      const {entries} = h.session;
111	
112	      expect(entries[1]).toMatchObject({role: 'assistant', content: 'hi there', isStreaming: false});
113	    });
114	  });
115	
116	  describe('thinking segments', () => {
117	    it('commits the thinking entry before the assistant entry opens', async () => {
118	      const h = harness([text('<thinking>pondering</thinking>answer'), STOP]);
119	
120	      await h.send();
121	
122	      expect(h.frames()).toEqual([
123	        'upsert 0 user "hello"',
124	        'upsert 1 thinking ""',
125	        'delta 1 "pondering"',
126	        'commit 1',
127	        'upsert 2 assistant ""',
128	        'delta 2 "answer"',
129	        'commit 2',
130	        'stream_end',
131	      ]);
132	    });
133	
134	    it('commits the thinking entry when text resumes, not when a tool entry appears', async () => {
135	      const h = harness([
136	        text('<thinking>I should look up the weather for Berlin.</thinking>'),
137	        {type: 'tool_use', toolCall: {id: 'c1', name: 'get_weather', input: {location: 'Berlin'}}} as MessageChunk,
138	        text('Berlin currently has '),
139	        text('a temperature of 18 degrees Celsius with clear skies.'),
140	        STOP,
141	      ]);
142	
143	      await h.send();
144	
145	      expect(h.frames()).toEqual([
146	        'upsert 0 user "hello"',
147	        'upsert 1 thinking ""',
148	        'delta 1 "I should look up the weather for Berlin."',
149	        'upsert 2 tool ""',
150	        'commit 1',
151	        'upsert 3 assistant ""',
152	        'delta 3 "Berlin currently has "',
153	        'delta 3 "a temperature of 18 degrees Celsius with clear skies."',
154	        'commit 3',
155	        'stream_end',
156	      ]);
157	    });
158	  });
159	
160	  describe('tool chunks', () => {
161	    it('sends a tool entry for a tool call', async () => {
162	      const h = harness([{type: 'tool_use', toolCall: {id: 'c1', name: 'lookup', input: {q: 1}}}, STOP]);
163	
164	      await h.send();
165	
166	      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'upsert 1 tool ""', 'stream_end']);
167	    });
168	
169	    it('forwards a tool result to the client untouched', async () => {
170	      const forwarded = {type: 'entry_commit', index: 41} as OutgoingMessage;
171	      const h = harness([{type: 'tool_result', clientMessages: [forwarded]} as MessageChunk, STOP]);
172	
173	      await h.send();
174	
175	      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'commit 41', 'stream_end']);
176	    });
177	  });
178	
179	  describe('suppression', () => {
180	    it('blanks an assistant entry that was already sent', async () => {
181	      const h = harness([text('leaked'), STOP, SUPPRESS]);
182	
183	      await h.send();
184	
185	      expect(h.frames()).toEqual([
186	        'upsert 0 user "hello"',
187	        'upsert 1 assistant ""',
188	        'delta 1 "leaked"',
189	        'commit 1',
190	        'upsert 1 assistant ""',
191	        'stream_end',
192	      ]);
193	    });
194	
195	    it('never blanks a thinking entry, only assistant ones', async () => {
196	      const h = harness([text('<thinking>private</thinking>said'), STOP, SUPPRESS]);
197	
198	      await h.send();
199	
200	      expect(h.frames().filter(frame => frame.startsWith('upsert 1'))).toEqual(['upsert 1 thinking ""']);
201	    });
202	
203	    it('skips rather than upserts a segment opened after suppression', async () => {
204	      const h = harness([SUPPRESS, text('hidden'), STOP]);
205	
206	      await h.send();
207	
208	      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'skip 1', 'stream_end']);
