210	
211	    it('still records a suppressed reply in the session, so history keeps it', async () => {
212	      const h = harness([SUPPRESS, text('hidden'), STOP]);
213	
214	      await h.send();
215	
216	      const {entries} = h.session;
217	
218	      expect(entries[1]).toMatchObject({role: 'assistant', content: 'hidden', isStreaming: false});
