247	      const h = harness([SUPPRESS, text('hidden'), STOP]);
248	
249	      await h.send();
250	
251	      const [, answer] = h.session.entries;
252	      expect(answer).toMatchObject({role: 'assistant', content: 'hidden', suppressed: true});
253	    });
254	
255	    it('leaves a thinking entry the client kept seeing unmarked, and marks the blanked answer', async () => {
256	      const h = harness([text('<thinking>private</thinking>said'), STOP, SUPPRESS]);
257	
258	      await h.send();
259	
260	      const [, thinking, answer] = h.session.entries;
261	      expect({thinking: 'suppressed' in thinking, answer}).toMatchObject({
262	        thinking: false,
263	        answer: {role: 'assistant', content: 'said', suppressed: true},
264	      });
265	    });
266	
267	    it('commits and retracts an answer still open when suppression begins, and skips what follows as a new entry', async () => {
268	      const h = harness([text('before'), SUPPRESS, text(' after'), STOP]);
269	
270	      await h.send();
271	
272	      const [, answer, after] = h.session.entries;
273	      expect({frames: h.frames(), answer, after}).toMatchObject({
274	        frames: [
275	          'upsert 0 user "hello"',
276	          'upsert 1 assistant ""',
277	          'delta 1 "before"',
278	          'commit 1',
279	          'upsert 1 assistant ""',
280	          'skip 2',
281	          'stream_end',
