287	
288	    it('commits a thought still open when suppression begins as the client saw it, and skips what follows', async () => {
289	      const h = harness([text('<thinking>early'), SUPPRESS, text(' later</thinking>'), STOP]);
290	
291	      await h.send();
292	
293	      const [, thought, after] = h.session.entries;
