309	
310	  describe('failures', () => {
311	    it('tells the client to retry when the provider is rate limited', async () => {
312	      // eslint-disable-next-line re-lint/no-flag-params -- AIError's retryable flag; see adrs/ADR-006-lint-suppressions.md
313	      const h = harness([], {failWith: new AIError('slow down', 'RATE_LIMITED', true)});
314	
315	      await h.send();
316	
317	      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'error RATE_LIMITED', 'stream_end']);
