331	      const h = harness([text('Half an ans')], {failWith: new Error('provider dropped')});
332	
333	      await h.send();
334	
335	      expect(h.frames()).toEqual([
336	        'upsert 0 user "hello"',
337	        'upsert 1 assistant ""',
338	        'delta 1 "Half an ans"',
339	        'upsert 1 assistant "Half an ans"',
340	        'commit 1',
341	        'error SERVER_ERROR',
342	        'stream_end',
343	      ]);
344	    });
345	
346	    const invalidRun = async (content: string) => {
347	      const h = harness([]);
348	      await h.send({type: 'user_message', content});
349	      const {calls} = h.processMessageStream.mock;
350	      return {frames: h.frames(), streams: calls.length};
