352	    const REFUSED = {frames: ['error INVALID_MESSAGE', 'stream_end'], streams: 0};
353	
354	    it('answers an empty user_message with INVALID_MESSAGE then stream_end', async () => {
355	      expect(await invalidRun('')).toEqual(REFUSED);
