450	      const lookup: MessageChunk = {type: 'tool_use', toolCall: {id: 'c1', name: 'lookup', input: {}}};
451	      const h = harness([text('Let me check'), lookup]);
452	
453	      await h.send();
454	
455	      const [, answer] = h.session.entries;
456	      expect({last: h.frames().slice(-2), open: stillStreaming(h.session), answer}).toMatchObject({
457	        last: ['commit 1', 'stream_end'],
458	        open: 0,
459	        answer: {role: 'assistant', content: 'Let me check', truncated: true},
460	      });
461	    });
462	
