468	      expect(h.frames().filter(frame => frame.startsWith('commit'))).toEqual(['commit 1', 'commit 2']);
469	    });
470	
471	    it('records the open entries under suppression without sending a commit when the provider throws', async () => {
472	      const h = harness([SUPPRESS, text('hidden')], {failWith: DROPPED});
473	
474	      await h.send();
475	
476	      expect({frames: h.frames(), open: stillStreaming(h.session)}).toEqual({
477	        frames: ['upsert 0 user "hello"', 'skip 1', 'error SERVER_ERROR', 'stream_end'],
478	        open: 0,
479	      });
480	    });
481	  });
482	
483	  describe('an entry cut short', () => {
484	    const DROPPED = new Error('provider dropped');
485	    const upsertsOf = (sent: OutgoingMessage[], index: number) =>
486	      sent.flatMap(frame => (frame.type === 'entry_upsert' && frame.index === index ? [frame.entry] : []));
487	
488	    it('flags a partial answer truncated in the session and re-sends it with the flag before its commit', async () => {
489	      const h = harness([text('partial answer')], {failWith: DROPPED});
