import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {validateMessage} from './validation.js';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../../types/session.js';
import type {OutgoingMessage, ConversationListMessage} from '../../types/messages.js';
import type {SessionSummary} from '../../types/sessionStore.js';

const harness = () => {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  return {
    session,
    sent,
    frames: () => sent,
    send: (raw: unknown) => {
      const handle = createMessageHandler({
        processMessageStream: async function* () {
          yield {type: 'stop', stopReason: 'end_turn'};
        },
      } as unknown as ChatOrchestrator);
      return handle(ws, session, raw);
    },
  };
};

describe('conversation list acceptance', () => {
  describe('validation', () => {
    it('accepts list_conversations with no parameters', () => {
      const result = validateMessage({type: 'list_conversations'});

      expect(result.valid).toBe(true);
    });

    it('accepts list_conversations with valid limit 1-200', () => {
      const result1 = validateMessage({type: 'list_conversations', limit: 1});
      const result50 = validateMessage({type: 'list_conversations', limit: 50});
      const result200 = validateMessage({type: 'list_conversations', limit: 200});

      expect(result1.valid).toBe(true);
      expect(result50.valid).toBe(true);
      expect(result200.valid).toBe(true);
    });

    it('rejects list_conversations with limit 0', () => {
      const result = validateMessage({type: 'list_conversations', limit: 0});

      expect(result.valid).toBe(false);
      expect('error' in result && result.error).toContain('limit');
    });

    it('rejects list_conversations with limit 201', () => {
      const result = validateMessage({type: 'list_conversations', limit: 201});

      expect(result.valid).toBe(false);
      expect('error' in result && result.error).toContain('limit');
    });

    it('rejects list_conversations with fractional limit 1.5', () => {
      const result = validateMessage({type: 'list_conversations', limit: 1.5});

      expect(result.valid).toBe(false);
      expect('error' in result && result.error).toContain('limit');
    });

    it('rejects list_conversations with string limit "10"', () => {
      const result = validateMessage({type: 'list_conversations', limit: '10'});

      expect(result.valid).toBe(false);
      expect('error' in result && result.error).toContain('limit');
    });

    it('rejects list_conversations with before not a valid cursor', () => {
      const result = validateMessage({type: 'list_conversations', before: 'not a date'});

      expect(result.valid).toBe(false);
      expect('error' in result && result.error).toContain('before');
    });
  });

  describe('message handler', () => {
    it('with history enabled, returns conversation_list with three summaries newest first', async () => {
      const now = new Date();
      const summaries: SessionSummary[] = [
        {sessionId: 's1', createdAt: new Date(now.getTime() - 2000), updatedAt: now, entryCount: 5},
        {sessionId: 's2', createdAt: new Date(now.getTime() - 3000), updatedAt: new Date(now.getTime() - 1000), entryCount: 3},
        {sessionId: 's3', createdAt: new Date(now.getTime() - 4000), updatedAt: new Date(now.getTime() - 2000), entryCount: 1},
      ];

      const store = {listFor: jest.fn(async () => summaries)};
      const handle = createMessageHandler({} as unknown as ChatOrchestrator);

      const sent: OutgoingMessage[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

      await (handle as any)(ws, session, {type: 'list_conversations'});

      const conversationListMessage = sent.find(m => m.type === 'conversation_list') as ConversationListMessage;
      expect(conversationListMessage).toBeDefined();
      expect(conversationListMessage.conversations).toHaveLength(3);
      expect(conversationListMessage.conversations[0].sessionId).toBe('s1');
    });

    it('uses ws.userId not the userId from the frame', async () => {
      const summaries: SessionSummary[] = [
        {sessionId: 's1', createdAt: new Date(), updatedAt: new Date(), entryCount: 1},
      ];

      const store = {listFor: jest.fn(async () => summaries)};
      const handle = createMessageHandler({} as unknown as ChatOrchestrator);

      const sent: OutgoingMessage[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      const session: ChatSession = {sessionId: 's1', userId: 'authenticated_user', entries: []};

      await (handle as any)(ws, session, {type: 'list_conversations', userId: 'another_user'});

      const conversationListMessage = sent.find(m => m.type === 'conversation_list');
      expect(conversationListMessage).toBeDefined();
    });

    it('passes limit and before to listFor', async () => {
      const summaries: SessionSummary[] = [];
      const store = {listFor: jest.fn(async () => summaries)};
      const handle = createMessageHandler({} as unknown as ChatOrchestrator);

      const sent: OutgoingMessage[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

      const before = {updatedAt: '2025-01-01T00:00:00Z', sessionId: 's0'};
      await (handle as any)(ws, session, {type: 'list_conversations', limit: 50, before});

      // TODO: verify store.listFor was called with limit and before
    });

    it('with history disabled, returns UNSUPPORTED error', async () => {
      const handle = createMessageHandler({} as unknown as ChatOrchestrator);

      const sent: OutgoingMessage[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

      await (handle as any)(ws, session, {type: 'list_conversations'});

      const errorMessage = sent.find(m => m.type === 'error');
      expect(errorMessage).toBeDefined();
      expect('code' in errorMessage && errorMessage.code).toBe('UNSUPPORTED');
    });

    it('with store not implementing listFor, returns UNSUPPORTED error', async () => {
      const store = {};
      const handle = createMessageHandler({} as unknown as ChatOrchestrator);

      const sent: OutgoingMessage[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

      await (handle as any)(ws, session, {type: 'list_conversations'});

      const errorMessage = sent.find(m => m.type === 'error');
      expect(errorMessage).toBeDefined();
      expect('code' in errorMessage && errorMessage.code).toBe('UNSUPPORTED');
    });

    it('ConversationListMessage has ISO string dates not Date objects', async () => {
      const now = new Date();
      const summaries: SessionSummary[] = [
        {sessionId: 's1', createdAt: now, updatedAt: now, entryCount: 1},
      ];

      const handle = createMessageHandler({} as unknown as ChatOrchestrator);

      const sent: OutgoingMessage[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

      await (handle as any)(ws, session, {type: 'list_conversations'});

      const conversationListMessage = sent.find(m => m.type === 'conversation_list') as ConversationListMessage;
      if (conversationListMessage && conversationListMessage.conversations.length > 0) {
        const summary = conversationListMessage.conversations[0];
        expect(typeof summary.createdAt).toBe('string');
        expect(typeof summary.updatedAt).toBe('string');
      }
    });

    it('answers list_conversations on non-locked path while user_message is streaming', async () => {
      // TODO: This test needs to verify that list_conversations answers immediately
      // without waiting for a user_message stream to complete on the same session
    });
  });
});

